using Microsoft.AspNetCore.Mvc; using Exercicio10_Eletronicos.Models; namespace Exercicio10_Eletronicos.Controllers; public class EletronicoController:Controller{private static readonly List<Eletronico> Dados=new(){new(){Id=1,Nome="Eletrônico 1",Marca="Marca 2",Categoria="Acessório",Preco=150,Estoque=1 },new(){Id=2,Nome="Eletrônico 2",Marca="Marca 3",Categoria="Celular",Preco=300,Estoque=2 },new(){Id=3,Nome="Eletrônico 3",Marca="Marca 1",Categoria="Computador",Preco=450,Estoque=0 },new(){Id=4,Nome="Eletrônico 4",Marca="Marca 2",Categoria="Acessório",Preco=600,Estoque=4 },new(){Id=5,Nome="Eletrônico 5",Marca="Marca 3",Categoria="Celular",Preco=750,Estoque=5 },new(){Id=6,Nome="Eletrônico 6",Marca="Marca 1",Categoria="Computador",Preco=900,Estoque=6 },new(){Id=7,Nome="Eletrônico 7",Marca="Marca 2",Categoria="Acessório",Preco=1050,Estoque=0 },new(){Id=8,Nome="Eletrônico 8",Marca="Marca 3",Categoria="Celular",Preco=1200,Estoque=8 },new(){Id=9,Nome="Eletrônico 9",Marca="Marca 1",Categoria="Computador",Preco=1350,Estoque=9 },new(){Id=10,Nome="Eletrônico 10",Marca="Marca 2",Categoria="Acessório",Preco=1500,Estoque=10 },new(){Id=11,Nome="Eletrônico 11",Marca="Marca 3",Categoria="Celular",Preco=1650,Estoque=11 },new(){Id=12,Nome="Eletrônico 12",Marca="Marca 1",Categoria="Computador",Preco=1800,Estoque=0 },}public IActionResult Index()=>View(Dados); public IActionResult EmEstoque()=>View("Index",Dados.Where(x=>x.Estoque>0)); public IActionResult Categoria(string nome="Acessório")=>View("Index",Dados.Where(x=>x.Categoria==nome)); public IActionResult AbaixoDe(int valor=1000)=>View("Index",Dados.Where(x=>x.Preco<valor));}
